#include <bits/stdc++.h>
using namespace std;

const int MOD = 51123987;
const int MAXN = 150;
const int CNT = 54;

int n;
char s[MAXN + 2];
int f[MAXN + 1][CNT][CNT][CNT];

void update(int &x, int y) {
    x = (x + y) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> (s + 1);

    f[0][0][0][0] = 1;
    int ans = 0;

    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= min(52, n); ++j) {
            for (int k = 0; k <= min(52, n - j); ++k) {
                for (int l = 0; l <= min(52, n - j - k); ++l) {
                    if (!f[i][j][k][l]) continue;

                    if (j + k + l == n &&
                        abs(j - k) <= 1 &&
                        abs(j - l) <= 1 &&
                        abs(k - l) <= 1) {
                        update(ans, f[i][j][k][l]);
                    }

                    int num[3] = {0, 0, 0};
                    if (i != 0) ++num[s[i] - 'a'];

                    for (int x = i + 1; x <= n; ++x) {
                        int c = s[x] - 'a';
                        if (num[c]++) continue;

                        if (c == 0)
                            update(f[x][j + 1][k][l], f[i][j][k][l]);
                        else if (c == 1)
                            update(f[x][j][k + 1][l], f[i][j][k][l]);
                        else
                            update(f[x][j][k][l + 1], f[i][j][k][l]);
                    }

                    if (i == 0) continue;

                    if (s[i] == 'a')
                        update(f[i][j + 1][k][l], f[i][j][k][l]);
                    else if (s[i] == 'b')
                        update(f[i][j][k + 1][l], f[i][j][k][l]);
                    else
                        update(f[i][j][k][l + 1], f[i][j][k][l]);
                }
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

